L21_1.m_Talk_KOREA = "\236\157\188 \235\133\132\236\151\144 \235\148\177 \237\149\156 \235\178\136 \236\151\172\235\138\148 \237\142\152\236\138\164\237\131\128\236\158\150\236\149\132\236\154\148! \234\183\184\235\159\176\235\141\176 \234\176\156\236\181\156 \235\139\185\236\157\188\236\151\144 \236\164\145\236\167\128 \236\132\160\236\150\184\236\157\180\235\157\188\235\139\136\236\154\148!?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "\228\184\128\229\185\180\227\129\171\228\184\128\229\186\166\227\129\174\227\131\149\227\130\167\227\130\185\227\130\191\227\129\167\227\129\153\227\130\136\239\188\129\n\227\129\170\227\129\174\227\129\171\233\150\139\229\130\172\229\189\147\230\151\165\227\129\171\228\184\173\230\173\162\229\174\163\232\168\128\227\130\146\227\129\153\227\130\139\227\130\147\227\129\167\227\129\153\227\129\139\239\188\129\239\188\159"
L21_1.m_Talk_ENG = "This festival only happens once a year! How can you cancel it last minute last this?!"
L21_1.m_Talk_TWN = "\233\128\153\230\152\175\228\184\128\229\185\180\228\184\128\230\172\161\231\154\132\229\173\184\229\156\146\231\165\173\230\172\184\239\188\129\230\128\142\233\186\188\229\143\175\228\187\165\229\156\168\230\180\187\229\139\149\231\149\182\229\164\169\230\137\141\229\150\138\229\129\156\239\188\129\239\188\159"
L21_1.m_Talk_DEU = "Es ist ein Festival, das nur einmal im Jahr stattfindet! Wie kannst du es also am Tag der Veranstaltung einfach absagen!?"
L21_1.m_Talk_FRA = "Ce festival n'a lieu qu'une fois par an ! On ne peut pas l'annuler comme \195\167a, et le jour m\195\170me en plus !"
