L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "\227\131\159\227\130\171\227\129\149\227\130\147\227\129\174\230\176\151\230\140\129\227\129\161\227\129\175\227\130\136\227\129\143\227\130\143\227\129\139\227\130\138\227\129\190\227\129\153\227\128\130\n\231\148\159\229\190\146\228\188\154\233\149\183\227\129\168\227\129\151\227\129\166\227\128\129\227\129\147\227\129\174\227\130\136\227\129\134\227\129\170\230\177\186\230\150\173\227\130\146\228\184\139\227\129\151\227\129\159\227\129\147\227\129\168\227\129\175\227\129\168\227\129\166\227\130\130\230\174\139\229\191\181\227\129\171\230\128\157\227\129\132\227\129\190\227\129\153\227\128\130"
L23_1.m_Talk_ENG = "I understand your frustration, Mika. And I deliver this news with a heavy heart as the Student President."
L23_1.m_Talk_TWN = "\231\177\179\229\141\161\239\188\140\230\136\145\230\152\142\231\153\189\228\189\160\231\154\132\229\191\131\230\131\133\227\128\130\232\186\171\231\130\186\229\173\184\231\148\159\230\156\131\230\156\131\233\149\183\239\188\140\230\136\145\228\185\159\229\190\136\233\129\186\230\134\190\229\129\154\229\135\186\233\128\153\229\128\139\230\177\186\229\174\154\227\128\130"
L23_1.m_Talk_DEU = "Ich kann ja verstehen, wie du dich f\195\188hlst, Mika. Als Pr\195\164sidentin des Sch\195\188lerparlaments bedauere ich es auch sehr, diese Entscheidung treffen zu m\195\188ssen."
L23_1.m_Talk_FRA = "Je comprends votre d\195\169ception, Mika. Sachez que cette d\195\169cision n'a pas \195\169t\195\169 facile \195\160 prendre."
