L33_1.m_Talk_DEU = "Hehe, aber da sich die Lieferung der S\195\188\195\159kartoffeln verz\195\182gert, w\195\164re es eigentlich besser, wenn das Festival noch etwas l\195\164nger verschoben werden k\195\182nnte."
