L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "\227\129\157\227\129\134\227\129\167\227\129\153\227\129\173\227\128\130\231\132\161\233\167\132\232\182\179\227\130\146\232\184\143\227\129\190\227\129\155\227\129\166\227\129\151\227\129\190\227\129\132\227\128\129\227\129\168\227\129\166\227\130\130\229\191\131\232\139\166\227\129\151\227\129\132\227\129\167\227\129\153\227\128\130"
L11_1.m_Talk_JPN = L12_1
