L14_1.m_fTalkTime = 0.03
L15_1 = "\227\130\136\227\129\143\232\129\158\227\129\132\227\129\166\227\129\143\227\129\160\227\129\149\227\129\132\227\128\129\227\131\159\227\131\138\227\129\149\227\130\147\227\128\130\231\164\190\228\188\154\228\186\186\227\129\168\227\129\175\230\128\157\227\129\163\227\129\166\227\130\139\227\130\136\227\130\138\227\130\130\227\129\164\227\130\137\227\129\132\227\130\130\227\129\174\227\129\167\227\129\153\227\128\130"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Listen carefully, Mina. Working at a company is harder than it looks."
