L16_1 = "\227\129\160\227\129\139\227\130\137\228\188\145\227\130\129\227\130\139\229\144\141\229\136\134\227\129\140\227\129\130\227\130\139\227\129\174\227\129\170\227\130\137\227\128\129\227\129\168\227\130\138\227\129\130\227\129\136\227\129\154\228\188\145\227\130\147\227\129\160\227\129\187\227\129\134\227\129\140\227\129\132\227\129\132\227\129\167\227\129\153\227\130\136\227\128\130"
